import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs/promises';import os from 'node:os';import path from 'node:path';import sharp from 'sharp';import {encodePng} from './images.mjs';import {message} from './mcp.mjs';

test('PIXI renders Slider instance values',{skip:!process.env.FGUI_CHROME||process.platform!=='win32',timeout:90000},async()=>{
 const root=await fs.mkdtemp(path.join(os.tmpdir(),'fgui-pixi-slider-'));try{
  const dir=path.join(root,'assets','Demo');await fs.mkdir(dir,{recursive:true});await fs.writeFile(path.join(root,'p.fairy'),'<projectDescription type="CocosCreator"/>');await fs.writeFile(path.join(dir,'package.xml'),'<packageDescription id="abcdefgh"><resources><component id="main" name="Main.xml" path="/" exported="true"/><component id="slider" name="Slider.xml" path="/"/></resources><publish name="Demo"/></packageDescription>');
  await fs.writeFile(path.join(dir,'Slider.xml'),'<component size="40,10" extention="Slider"><displayList><graph id="g" name="bar" xy="0,0" size="40,10" type="rect" lineSize="0" fillColor="#ffff0000"/></displayList><Slider/></component>');
  await fs.writeFile(path.join(dir,'Main.xml'),'<component size="40,10"><displayList><component id="s" src="slider" xy="0,0"><Slider value="25" max="100"/></component></displayList></component>');
  const response=await message({jsonrpc:'2.0',id:1,method:'tools/call',params:{name:'screenshot',arguments:{project:root,pkg:'Demo',name:'Main',width:40,height:10,settle_ms:0}}});assert.equal(response.result.isError,false,response.result.content[0].text);
  const {data,info}=await sharp(Buffer.from(response.result.content[1].data,'base64')).removeAlpha().raw().toBuffer({resolveWithObject:true});const pixel=(x,y)=>[...data.subarray((y*info.width+x)*3,(y*info.width+x)*3+3)];assert.deepEqual(pixel(5,5),[255,0,0]);assert.deepEqual(pixel(20,5),[51,51,51]);
 }finally{await fs.rm(root,{recursive:true,force:true});}
});

