test('PIXI applies the selected page to a paginated list',{skip:!process.env.FGUI_CHROME||process.platform!=='win32',timeout:120000},async()=>{
 const root=await fs.mkdtemp(path.join(os.tmpdir(),'fgui-pixi-page-'));try{
  const dir=path.join(root,'assets','Demo');await fs.mkdir(dir,{recursive:true});await fs.writeFile(path.join(root,'p.fairy'),'<projectDescription type="CocosCreator"/>');await fs.writeFile(path.join(dir,'package.xml'),'<packageDescription id="abcdefgh"><resources><component id="main" name="Main.xml" path="/" exported="true"/><component id="red" name="Red.xml" path="/"/><component id="green" name="Green.xml" path="/"/></resources><publish name="Demo"/></packageDescription>');
  for(const [name,color] of [['Red','#ffff0000'],['Green','#ff00ff00']])await fs.writeFile(path.join(dir,name+'.xml'),`<component size="20,20"><displayList><graph id="g" xy="0,0" size="20,20" type="rect" lineSize="0" fillColor="${color}"/></displayList></component>`);
  const capture=async selected=>{await fs.writeFile(path.join(dir,'Main.xml'),`<component size="20,20"><controller name="page" pages="0,first,1,second" selected="${selected}"/><displayList><list id="l" xy="0,0" size="20,20" layout="pagination" lineItemCount="1" lineItemCount2="1" autoItemSize="false" overflow="scroll" scroll="horizontal" scrollBarFlags="8" pageController="page"><item url="ui://abcdefghred"/><item url="ui://abcdefghgreen"/></list></displayList></component>`);const response=await message({jsonrpc:'2.0',id:1,method:'tools/call',params:{name:'screenshot',arguments:{project:root,pkg:'Demo',name:'Main',width:20,height:20,settle_ms:0}}});assert.equal(response.result.isError,false,response.result.content[0].text);return sharp(Buffer.from(response.result.content[1].data,'base64')).removeAlpha().raw().toBuffer();};
  const first=await capture(0),second=await capture(1),pixel=data=>[...data.subarray((10*20+10)*3,(10*20+10)*3+3)];assert.deepEqual(pixel(first),[255,0,0]);assert.deepEqual(pixel(second),[0,255,0]);
 }finally{await fs.rm(root,{recursive:true,force:true});}
});

