test('PIXI preview applies selected text and image color gears',{skip:!process.env.FGUI_CHROME||process.platform!=='win32',timeout:90000},async()=>{const root=await fs.mkdtemp(path.join(os.tmpdir(),'fgui-pixi-gears-style-'));try{const dir=path.join(root,'assets','Demo');await fs.mkdir(dir,{recursive:true});await fs.writeFile(path.join(root,'p.fairy'),'<projectDescription type="CocosCreator"/>');await fs.writeFile(path.join(dir,'package.xml'),'<packageDescription id="abcdefgh"><resources><image id="white" name="White.png" path="/"/><component id="main" name="Main.xml" path="/" exported="true"/></resources><publish name="Demo"/></packageDescription>');await fs.writeFile(path.join(dir,'White.png'),await encodePng({width:10,height:10,pixels:Buffer.from(Array.from({length:100},()=>[255,255,255,255]).flat())}));const file=path.join(dir,'Main.xml');const source='<component size="100,100"><controller name="state" pages="a,A,b,B" selected="1"/><displayList><image id="i" xy="10,10" src="white"><gearColor controller="state" pages="a,b" values="#ff0000|#00ff00"/></image><text id="t" xy="10,35" size="80,50" color="#ff0000" fontSize="32" text=""><gearText controller="state" pages="a,b" values="|TEST"/></text><text id="empty" xy="10,75" size="80,20" color="#0000ff" fontSize="16" text="BAD"><gearText controller="state" pages="b" values=""/></text></displayList></component>';await fs.writeFile(file,source);const call=()=>message({jsonrpc:'2.0',id:1,method:'tools/call',params:{name:'screenshot',arguments:{project:root,pkg:'Demo',name:'Main',renderer:'pixi',width:100,height:100,settle_ms:0}}});const response=await call();assert.equal(response.result.isError,false,response.result.content[0].text);const {data,info}=await sharp(Buffer.from(response.result.content[1].data,'base64')).removeAlpha().raw().toBuffer({resolveWithObject:true});const pixel=(x,y)=>[...data.subarray((y*info.width+x)*3,(y*info.width+x)*3+3)];assert.deepEqual(pixel(15,15),[0,255,0]);let red=0;for(let y=35;y<90;y++)for(let x=10;x<90;x++){const p=pixel(x,y);if(p[0]>150&&p[1]<80&&p[2]<80)red++;}assert.ok(red>20,'selected text is rendered');let blue=0;for(let y=75;y<100;y++)for(let x=0;x<100;x++){const p=pixel(x,y);if(p[2]>150&&p[0]<80&&p[1]<80)blue++;}assert.equal(blue,0,'empty selected text overrides source text');assert.equal(await fs.readFile(file,'utf8'),source);await fs.writeFile(file,source.replace('#00ff00','#00ff00,#ffffff'));const dual=await call();assert.equal(dual.result.isError,false,dual.result.content[0].text);const dualPixels=await sharp(Buffer.from(dual.result.content[1].data,'base64')).removeAlpha().raw().toBuffer();const offset=(15*info.width+15)*3;assert.deepEqual([...dualPixels.subarray(offset,offset+3)],[0,255,0]);}finally{await fs.rm(root,{recursive:true,force:true})}});


