test('PIXI preview applies button icon and empty title overrides',{skip:!process.env.FGUI_CHROME||process.platform!=='win32',timeout:90000},async()=>{const root=await fs.mkdtemp(path.join(os.tmpdir(),'fgui-pixi-button-icon-'));try{const dir=path.join(root,'assets','Demo');await fs.mkdir(dir,{recursive:true});await fs.writeFile(path.join(root,'p.fairy'),'<projectDescription type="CocosCreator"/>');await fs.writeFile(path.join(dir,'package.xml'),'<packageDescription id="abcdefgh"><resources><image id="red" name="Red.png" path="/"/><component id="main" name="Main.xml" path="/" exported="true"/><component id="button" name="Button.xml" path="/"/></resources><publish name="Demo"/></packageDescription>');await fs.writeFile(path.join(dir,'Red.png'),await encodePng({width:10,height:10,pixels:Buffer.from(Array.from({length:100},()=>[255,0,0,255]).flat())}));await fs.writeFile(path.join(dir,'Button.xml'),'<component size="80,40" extention="Button"><displayList><loader id="icon" name="icon" xy="0,0" size="10,10"/><text id="title" name="title" xy="20,0" size="60,30" fontSize="20" color="#ffffff" text="OLD"/></displayList><Button/></component>');await fs.writeFile(path.join(dir,'Main.xml'),'<component size="100,100"><displayList><component id="btn" xy="10,10" src="button"><Button title="" icon="ui://Demo/Red"/></component></displayList></component>');const response=await message({jsonrpc:'2.0',id:1,method:'tools/call',params:{name:'screenshot',arguments:{project:root,pkg:'Demo',name:'Main',renderer:'pixi',width:100,height:100,settle_ms:0}}});assert.equal(response.result.isError,false,response.result.content[0].text);const {data,info}=await sharp(Buffer.from(response.result.content[1].data,'base64')).removeAlpha().raw().toBuffer({resolveWithObject:true});const pixel=(x,y)=>[...data.subarray((y*info.width+x)*3,(y*info.width+x)*3+3)];assert.deepEqual(pixel(15,15),[255,0,0]);let white=0;for(let y=10;y<40;y++)for(let x=30;x<90;x++){const p=pixel(x,y);if(p.every(v=>v>180))white++;}assert.equal(white,0,'empty override removes default text');}finally{await fs.rm(root,{recursive:true,force:true})}});


