test('PIXI screenshot cache reuses exact inputs and invalidates on source changes',{skip:!process.env.FGUI_CHROME||process.platform!=='win32',timeout:120000},async()=>{const root=await fs.mkdtemp(path.join(os.tmpdir(),'fgui-pixi-cache-'));try{const dir=path.join(root,'assets','Demo');await fs.mkdir(dir,{recursive:true});await fs.writeFile(path.join(root,'p.fairy'),'<projectDescription type="CocosCreator"/>');await fs.writeFile(path.join(dir,'package.xml'),'<packageDescription id="abcdefgh"><resources><component id="main" name="Main.xml" path="/" exported="true"/></resources><publish name="Demo"/></packageDescription>');const file=path.join(dir,'Main.xml'),source='<component size="100,100"><displayList><graph id="g" xy="10,10" size="20,20" type="rect" lineSize="0" fillColor="#ffff0000"/></displayList></component>';await fs.writeFile(file,source);const call=(extra={})=>message({jsonrpc:'2.0',id:1,method:'tools/call',params:{name:'screenshot',arguments:{project:root,pkg:'Demo',name:'Main',renderer:'pixi',width:100,height:100,settle_ms:0,reuse_screenshot:true,...extra}}});const first=await call();assert.equal(first.result.isError,false,first.result.content[0].text);assert.equal(JSON.parse(first.result.content[0].text).data.cached,false);const output=path.join(root,'copy.png'),second=await call({output});assert.equal(second.result.isError,false,second.result.content[0].text);assert.equal(JSON.parse(second.result.content[0].text).data.cached,true);assert.deepEqual(await fs.readFile(output),Buffer.from(first.result.content[1].data,'base64'));const existing=await call({output});assert.equal(existing.result.isError,true);assert.match(existing.result.content[0].text,/output must not already exist/);const stamp=(await fs.stat(file)).mtime;await fs.writeFile(file,source.replace('#ffff0000','#ff00ff00'));await fs.utimes(file,stamp,stamp);const third=await call();assert.equal(third.result.isError,false,third.result.content[0].text);assert.equal(JSON.parse(third.result.content[0].text).data.cached,false);const {data,info}=await sharp(Buffer.from(third.result.content[1].data,'base64')).removeAlpha().raw().toBuffer({resolveWithObject:true});const offset=(15*info.width+15)*3;assert.deepEqual([...data.subarray(offset,offset+3)],[0,255,0]);await fs.mkdir(path.join(root,'settings'));await fs.writeFile(path.join(root,'settings','Common.json'),JSON.stringify({scrollBars:{defaultDisplay:'hidden'}}));const fourth=await call();assert.equal(fourth.result.isError,false,fourth.result.content[0].text);assert.equal(JSON.parse(fourth.result.content[0].text).data.cached,false,'settings changes invalidate screenshots');}finally{await fs.rm(root,{recursive:true,force:true})}});


test('PIXI preview renders progress bars with instance values',{skip:!process.env.FGUI_CHROME||process.platform!=='win32',timeout:90000},async()=>{const root=await fs.mkdtemp(path.join(os.tmpdir(),'fgui-pixi-progress-'));try{const dir=path.join(root,'assets','Demo');await fs.mkdir(dir,{recursive:true});await fs.writeFile(path.join(root,'p.fairy'),'<projectDescription type="CocosCreator"/>');await fs.writeFile(path.join(dir,'package.xml'),'<packageDescription id="abcdefgh"><resources><component id="main" name="Main.xml" path="/" exported="true"/><component id="progress" name="Progress.xml" path="/"/></resources><publish name="Demo"/></packageDescription>');await fs.writeFile(path.join(dir,'Progress.xml'),'<component size="80,20" extention="ProgressBar"><displayList><graph id="bar" name="bar" xy="0,0" size="80,20" type="rect" lineSize="0" fillColor="#ffff0000"/></displayList></component>');const file=path.join(dir,'Main.xml');const xml='<component size="100,100"><displayList><component id="c" xy="10,10" src="progress"><ProgressBar value="30" max="100"/></component><component id="d" xy="10,40" src="progress"><ProgressBar/></component></displayList></component>';await fs.writeFile(file,xml);const call=()=>message({jsonrpc:'2.0',id:1,method:'tools/call',params:{name:'screenshot',arguments:{project:root,pkg:'Demo',name:'Main',renderer:'pixi',width:100,height:100,settle_ms:0}}});const response=await call();assert.equal(response.result.isError,false,response.result.content[0].text);const {data,info}=await sharp(Buffer.from(response.result.content[1].data,'base64')).removeAlpha().raw().toBuffer({resolveWithObject:true});const pixel=(x,y)=>[...data.subarray((y*info.width+x)*3,(y*info.width+x)*3+3)];assert.deepEqual(pixel(15,15),[255,0,0]);assert.deepEqual(pixel(40,15),[51,51,51]);assert.deepEqual(pixel(45,45),[255,0,0]);assert.deepEqual(pixel(55,45),[51,51,51]);await fs.writeFile(file,xml.replace('value="30" max="100"','value="40" max="100" min="20"'));const ranged=await call();assert.equal(ranged.result.isError,false,ranged.result.content[0].text);const raw=await sharp(Buffer.from(ranged.result.content[1].data,'base64')).removeAlpha().raw().toBuffer();const at=(x,y)=>[...raw.subarray((y*info.width+x)*3,(y*info.width+x)*3+3)];assert.deepEqual(at(28,15),[255,0,0]);assert.deepEqual(at(31,15),[51,51,51]);}finally{await fs.rm(root,{recursive:true,force:true})}});


