test('PIXI preview applies text color and outline gears',{skip:!process.env.FGUI_CHROME||process.platform!=='win32',timeout:90000},async()=>{const root=await fs.mkdtemp(path.join(os.tmpdir(),'fgui-pixi-text-gear-'));try{const dir=path.join(root,'assets','Demo');await fs.mkdir(dir,{recursive:true});await fs.writeFile(path.join(root,'p.fairy'),'<projectDescription type="CocosCreator"/>');await fs.writeFile(path.join(dir,'package.xml'),'<packageDescription id="abcdefgh"><resources><component id="main" name="Main.xml" path="/" exported="true"/></resources><publish name="Demo"/></packageDescription>');await fs.writeFile(path.join(dir,'Main.xml'),'<component size="200,100"><controller name="state" pages="a,A,b,B" selected="1"/><displayList><text id="t" xy="10,10" size="170,60" fontSize="32" color="#ffffff" strokeColor="#ff0000" bold="true" text="TEST"><gearColor controller="state" pages="a,b" values="#ffffff,#ff0000|#00ff00,#0000ff"/></text></displayList></component>');const response=await message({jsonrpc:'2.0',id:1,method:'tools/call',params:{name:'screenshot',arguments:{project:root,pkg:'Demo',name:'Main',renderer:'pixi',width:200,height:100,settle_ms:0}}});assert.equal(response.result.isError,false,response.result.content[0].text);const {data}=await sharp(Buffer.from(response.result.content[1].data,'base64')).removeAlpha().raw().toBuffer({resolveWithObject:true});let green=0,blue=0,red=0;for(let i=0;i<data.length;i+=3){if(data[i+1]>150&&data[i]<80&&data[i+2]<80)green++;if(data[i+2]>150&&data[i]<80&&data[i+1]<80)blue++;if(data[i]>150&&data[i+1]<80&&data[i+2]<80)red++;}assert.ok(green>10,'selected text color');assert.ok(blue>10,'selected outline color');assert.equal(red,0,'old outline is replaced');}finally{await fs.rm(root,{recursive:true,force:true})}});


test('PIXI preview applies font-size gears for selected controller pages',{skip:!process.env.FGUI_CHROME||process.platform!=='win32',timeout:90000},async()=>{const root=await fs.mkdtemp(path.join(os.tmpdir(),'fgui-pixi-fontsize-'));try{const dir=path.join(root,'assets','Demo');await fs.mkdir(dir,{recursive:true});await fs.writeFile(path.join(root,'p.fairy'),'<projectDescription type="CocosCreator"/>');await fs.writeFile(path.join(dir,'package.xml'),'<packageDescription id="abcdefgh"><resources><component id="main" name="Main.xml" path="/" exported="true"/></resources><publish name="Demo"/></packageDescription>');const file=path.join(dir,'Main.xml');const source='<component size="200,100"><controller name="state" pages="a,A,b,B" selected="1"/><displayList><text id="t" xy="10,10" size="170,70" fontSize="12" color="#ffffff" text="TEST"><gearFontSize controller="state" pages="a,b" values="12|36"/></text></displayList></component>';await fs.writeFile(file,source);const call=()=>message({jsonrpc:'2.0',id:1,method:'tools/call',params:{name:'screenshot',arguments:{project:root,pkg:'Demo',name:'Main',renderer:'pixi',width:200,height:100,settle_ms:0}}});const response=await call();assert.equal(response.result.isError,false,response.result.content[0].text);const pixels=await sharp(Buffer.from(response.result.content[1].data,'base64')).removeAlpha().raw().toBuffer();let white=0;for(let i=0;i<pixels.length;i+=3)if(pixels[i]>180&&pixels[i+1]>180&&pixels[i+2]>180)white++;assert.ok(white>100,'large selected text is visible');await fs.writeFile(file,source.replace('selected="1"','selected="0"'));const small=await call();assert.equal(small.result.isError,false,small.result.content[0].text);const smallPixels=await sharp(Buffer.from(small.result.content[1].data,'base64')).removeAlpha().raw().toBuffer();let smallWhite=0;for(let i=0;i<smallPixels.length;i+=3)if(smallPixels[i]>180&&smallPixels[i+1]>180&&smallPixels[i+2]>180)smallWhite++;assert.ok(white>smallWhite*3,'font size changes selected rendering');}finally{await fs.rm(root,{recursive:true,force:true})}});

