test('PIXI combines two display gears with AND and OR',{skip:!process.env.FGUI_CHROME||process.platform!=='win32',timeout:90000},async()=>{
 const root=await fs.mkdtemp(path.join(os.tmpdir(),'fgui-pixi-display2-'));
 try{const dir=path.join(root,'assets','Demo');await fs.mkdir(dir,{recursive:true});await fs.writeFile(path.join(root,'p.fairy'),'<projectDescription type="CocosCreator"/>');await fs.writeFile(path.join(dir,'package.xml'),'<packageDescription id="abcdefgh"><resources><component id="main" name="Main.xml" path="/" exported="true"/></resources><publish name="Demo"/></packageDescription>');let graphs='';for(let condition=0;condition<2;condition++)for(let i=0;i<4;i++){const primary=i>>1,secondary=i&1;graphs+=`<graph id="g${condition}${i}" xy="${i*25},${condition*25}" size="20,20" type="rect" lineSize="0" fillColor="#ffff0000"><gearDisplay controller="a" pages="${primary}"/><gearDisplay2 controller="b" pages="${secondary}" condition="${condition}"/></graph>`;}await fs.writeFile(path.join(dir,'Main.xml'),`<component size="100,50"><controller name="a" pages="0,first,1,second"/><controller name="b" pages="0,first,1,second"/><displayList>${graphs}</displayList></component>`);const response=await message({jsonrpc:'2.0',id:1,method:'tools/call',params:{name:'screenshot',arguments:{project:root,pkg:'Demo',name:'Main',renderer:'pixi',width:100,height:50,settle_ms:0}}});assert.equal(response.result.isError,false,response.result.content[0].text);const {data,info}=await sharp(Buffer.from(response.result.content[1].data,'base64')).removeAlpha().raw().toBuffer({resolveWithObject:true});const pixel=(x,y)=>[...data.subarray((y*info.width+x)*3,(y*info.width+x)*3+3)];for(let c=0;c<2;c++)for(let i=0;i<4;i++){const a=(i>>1)===0,b=(i&1)===0,shown=c===0?a&&b:a||b;assert.deepEqual(pixel(i*25+10,c*25+10),shown?[255,0,0]:[51,51,51],`condition ${c} case ${i}`);}}finally{await fs.rm(root,{recursive:true,force:true});}
});

