test('PIXI coalesces concurrent identical screenshot requests',{skip:!process.env.FGUI_CHROME||process.platform!=='win32',timeout:90000},async()=>{
 const root=await fs.mkdtemp(path.join(os.tmpdir(),'fgui-pixi-inflight-'));
 try{const dir=path.join(root,'assets','Demo');await fs.mkdir(dir,{recursive:true});await fs.writeFile(path.join(root,'p.fairy'),'<projectDescription type="CocosCreator"/>');await fs.writeFile(path.join(dir,'package.xml'),'<packageDescription id="abcdefgh"><resources><component id="main" name="Main.xml" path="/" exported="true"/></resources><publish name="Demo"/></packageDescription>');await fs.writeFile(path.join(dir,'Main.xml'),'<component size="40,40"><displayList><graph id="g" xy="0,0" size="20,20" type="rect" lineSize="0" fillColor="#ffff0000"/></displayList></component>');const outputs=[path.join(root,'one.png'),path.join(root,'two.png')],call=output=>message({jsonrpc:'2.0',id:1,method:'tools/call',params:{name:'screenshot',arguments:{project:root,pkg:'Demo',name:'Main',renderer:'pixi',width:40,height:40,settle_ms:0,reuse_screenshot:true,output}}});const responses=await Promise.all(outputs.map(call));for(const response of responses)assert.equal(response.result.isError,false,response.result.content[0].text);assert.deepEqual(responses.map(r=>JSON.parse(r.result.content[0].text).data.cached).sort(),[false,true]);assert.equal(responses[0].result.content[1].data,responses[1].result.content[1].data);assert.deepEqual(await fs.readFile(outputs[0]),await fs.readFile(outputs[1]));const shared=path.join(root,'shared.png'),sameOutput=await Promise.all([call(shared),call(shared)]);assert.equal(sameOutput.filter(r=>!r.result.isError).length,1);assert.equal(sameOutput.filter(r=>r.result.isError).length,1);assert.deepEqual(await fs.readFile(shared),await fs.readFile(outputs[0]));}finally{await fs.rm(root,{recursive:true,force:true});}
});

test('PIXI renders quarter and half radial image fills',{skip:!process.env.FGUI_CHROME||process.platform!=='win32',timeout:90000},async()=>{
 const root=await fs.mkdtemp(path.join(os.tmpdir(),'fgui-pixi-radial-'));
 try{const dir=path.join(root,'assets','Demo');await fs.mkdir(dir,{recursive:true});await fs.writeFile(path.join(root,'p.fairy'),'<projectDescription type="CocosCreator"/>');await fs.writeFile(path.join(dir,'package.xml'),'<packageDescription id="abcdefgh"><resources><component id="main" name="Main.xml" path="/" exported="true"/><image id="img" name="Icon.png" path="/"/></resources><publish name="Demo"/></packageDescription>');await sharp({create:{width:80,height:80,channels:4,background:'#ff0000'}}).png().toFile(path.join(dir,'Icon.png'));await fs.writeFile(path.join(dir,'Main.xml'),'<component size="180,80"><displayList><image id="a" src="img" xy="0,0" fillMethod="radial90" fillAmount="50"/><image id="b" src="img" xy="100,0" fillMethod="radial180" fillAmount="50"/></displayList></component>');const response=await message({jsonrpc:'2.0',id:1,method:'tools/call',params:{name:'screenshot',arguments:{project:root,pkg:'Demo',name:'Main',renderer:'pixi',width:180,height:80,settle_ms:0}}});assert.equal(response.result.isError,false,response.result.content[0].text);const {data,info}=await sharp(Buffer.from(response.result.content[1].data,'base64')).removeAlpha().raw().toBuffer({resolveWithObject:true});const pixel=(x,y)=>[...data.subarray((y*info.width+x)*3,(y*info.width+x)*3+3)];assert.deepEqual(pixel(60,10),[255,0,0]);assert.deepEqual(pixel(10,60),[51,51,51]);assert.deepEqual(pixel(160,40),[255,0,0]);assert.deepEqual(pixel(120,40),[51,51,51]);const file=path.join(dir,'Main.xml');await fs.writeFile(file,(await fs.readFile(file,'utf8')).replaceAll('fillAmount="50"','fillAmount="50" fillClockwise="false"'));const reverse=await message({jsonrpc:'2.0',id:2,method:'tools/call',params:{name:'screenshot',arguments:{project:root,pkg:'Demo',name:'Main',renderer:'pixi',width:180,height:80,settle_ms:0}}});assert.equal(reverse.result.isError,false,reverse.result.content[0].text);const raw=await sharp(Buffer.from(reverse.result.content[1].data,'base64')).removeAlpha().raw().toBuffer();const at=(x,y)=>[...raw.subarray((y*180+x)*3,(y*180+x)*3+3)];assert.deepEqual(at(60,10),[51,51,51]);assert.deepEqual(at(10,60),[255,0,0]);assert.deepEqual(at(160,40),[51,51,51]);assert.deepEqual(at(120,40),[255,0,0]);}finally{await fs.rm(root,{recursive:true,force:true});}
});

